impl ThreadPoolRecordBuilder {
    /// Builds a [`ThreadPoolRecord`].
    pub fn build(self) -> ThreadPoolRecord {
        ThreadPoolRecord {
            node_name: self.node_name,
            node_id: self.node_id,
            ephemeral_node_id: self.ephemeral_node_id,
            pid: self.pid,
            host: self.host,
            ip: self.ip,
            port: self.port,
            name: self.name,
            r#type: self.r#type,
            active: self.active,
            pool_size: self.pool_size,
            queue: self.queue,
            queue_size: self.queue_size,
            rejected: self.rejected,
            largest: self.largest,
            completed: self.completed,
            core: self.core,
            max: self.max,
            size: self.size,
            keep_alive: self.keep_alive,
        }
    }
}

impl crate::typed::builder::Build for ThreadPoolRecordBuilder {
    type Output = ThreadPoolRecord;

    fn build(self) -> ThreadPoolRecord {
        Self::build(self)
    }
}

impl From<ThreadPoolRecordBuilder> for ThreadPoolRecord {
    fn from(builder: ThreadPoolRecordBuilder) -> Self {
        builder.build()
    }
}
